(() => {
  'use strict';
  const C=OSLabConcurrencyMovies,P=C.phase,E=C.esc,node=C.node;
  const $=id=>document.getElementById(id);
  function exposeSelector(id,anchor){const label=$(id).closest('label');label.classList.add('cm-selector');anchor.before(label);}
  function register(){const detail=C.wrap('register-flow',['#cf-register-demo'],'手动切换信号与查看波形');
    C.mount({id:'register-flow',before:detail,action:()=>{detail.open=true;detail.scrollIntoView({block:'nearest',behavior:'instant'});},actionLabel:()=> '手动改变输入与时钟',
      build(){let s={data:0,clock:0,held:0};const phases=[P(s,'寄存器保存的值不会跟着输入随时变化','左边是输入 D，右边是已保存的 Q。这个存储单元只在时钟上升沿接收输入。',{duration:1500,id:'start'})];
        const words=[['输入变成 1，保存的值仍是 0','只有 D 改变；没有时钟上升沿，Q 继续保持原来的 0。'],['上升沿到来，寄存器接收 1','输入 D 仍为 1；寄存器保存了一份相同的值，Q 更新为 1。'],['输入变回 0，保存的 1 没有丢失','时钟保持在高电平也不会继续接收输入。Q 要等下一次上升沿。'],['时钟下降，寄存器继续保持 1','下降沿不触发这个存储单元，Q 仍为 1。'],['下一个上升沿到来，寄存器才接收 0','只有这次上升沿让 Q 从 1 变为 0。输入的变化与保存时刻是两件事。']];
        ['data','clock','data','clock','clock'].forEach((kind,i)=>{const before=s;s=OSLabCPUVisuals.registerTransition(s,kind);const rising=kind==='clock'&&s.clock===1;phases.push(P(s,...words[i],{before,duration:1800,id:'signal-'+i,rising,moves:rising?[{from:'clock-input',to:'clock-held',text:s.data,type:'cm-copy'}]:[],during:'时钟上升沿打开采样通路',duringNote:'输入的值正在被接收；原来的 Q 会保持到本次更新完成。'}));});return{context:'时钟决定接收时刻，存储电路保留结果',phases};},
      view(s,{phase,moving}){return '<div class="cm-clock-scene" data-open="'+Boolean(phase.rising)+'">'+node('clock-input','输入 D',s.data,'cm-register')+'<div class="cm-clock-gate"><b>'+(phase.rising?'↑':'│')+'</b><strong>'+(phase.rising?'上升沿采样':'保持原值')+'</strong><span>CLK = '+(moving?phase.state.clock:s.clock)+'</span></div>'+node('clock-held','保存的 Q',s.held,'cm-memory')+'<div class="cm-clock-feedback"><span>保留 Q</span><i>↶</i></div></div>';}
    });
  }
  function program(){const original=$('cf-program-demo');exposeSelector('cf-input-n',original);const detail=C.wrap('program-flow',[original],'查看指令、寄存器与逐条执行');
    C.mount({id:'program-flow',before:detail,controls:['#cf-input-n'],action:()=>{const input=$('cf-input-n');input.value=input.value==='0'?'3':'0';input.dispatchEvent(new Event('change'));},actionLabel:()=> $('cf-input-n').value==='0'?'对照 N = 3':'对照 N = 0',
      build(){const input=Number($('cf-input-n').value),frames=OSLabCPUProgram.programFrames(input),phases=[];phases.push(P(frames[0],input===0?'输入 N = 0，不需要执行累加':'把 1 到 '+input+' 累加，反复使用同一套电路','输入 N 决定循环次数；sum 保存累计结果，i 表示这一轮要加的数字。',{duration:1200,id:'start'}));
        phases.push(P(frames[3],'输入已读入，累计和从 0 开始','N 保存在寄存器中；sum = 0，i = 1。循环先检查 i 是否超过 N。',{before:frames[0],id:'load',duration:1500,moves:[{from:'loop-input',to:'loop-limit',text:input,type:'cm-copy'}],during:'把输入复制到寄存器 N',duringNote:'读取会保留内存中的输入；寄存器得到一份计算用的副本。'}));
        frames.forEach((s,i)=>{if(i<4)return;const before=frames[i-1];if(before.pc===3)phases.push(P(s,s.pc===7?'i = '+s.i+' 已超过 N = '+input+'，退出循环':'i = '+s.i+' 未超过 N = '+input+'，继续累加',s.pc===7?'比较让程序转向写回结果；此刻累计和还在寄存器里。':'条件允许继续，当前的 i 将交给同一个加法器。',{before,duration:1000,id:'compare-'+s.i,focus:'compare'}));
          else if(before.pc===4)phases.push(P(s,before.sum+' + '+s.i+' = '+s.sum+'，累计和留在 sum 中','每轮使用同一加法器，只是输入 i 和保存的累计和发生变化。',{before,id:'add-'+s.i,duration:1400,focus:'add',moves:[{from:'loop-i',to:'loop-sum',text:'+'+s.i,type:'cm-copy'}],during:'把 '+s.i+' 加入当前累计和 '+before.sum,duringNote:'计算结果尚未写回内存；这轮更新的目标是 sum 寄存器。'}));
          else if(before.pc===6)phases.push(P(s,'i 更新为 '+s.i+'，程序跳回同一个比较位置','sum = '+s.sum+' 继续保留，循环不会重新清零，也不会新造一套加法器。',{before:frames[i-2],id:'repeat-'+s.i,duration:1100,focus:'repeat',moves:[{from:'loop-repeat',to:'loop-compare',text:'PC',type:'cm-control'}],during:'跳回比较位置，开始下一轮',duringNote:'这一次跳转复用原来的指令；已累计的 sum 保持不变。'}));
          else if(s.done)phases.push(P(s,'循环结束，内存中的结果为 '+s.result,input===0?'第一次比较就退出，没有执行累加，最终写回 0。':'1 到 '+input+' 的累计和为 '+s.result+'。同一组指令和电路完成了所有轮次。',{before,id:'result',duration:2000,moves:[{from:'loop-sum',to:'loop-output',text:s.result,type:'cm-copy'}],during:'把最终的 sum 写回内存',duringNote:'内存结果在写入完成后改变；寄存器中的累计和仍然保留。'}));
        });return{context:'程序循环：改变数据，复用电路与指令',input,phases};},
      view(s,{story,phase}){return '<div class="cm-loop-scene"><div class="cm-loop-memory">'+node('loop-input','内存输入 N',story.input)+node('loop-output','内存结果',s.result??'未写入')+'</div><div class="cm-loop-circuit"><div class="cm-loop-check" data-node="loop-compare"><strong>'+(s.i===null?'先比较':s.i+' ≤ '+story.input+'：'+(s.i<=story.input?'继续':'退出'))+'</strong>'+node('loop-limit','寄存器 N',s.n??'—')+'</div><div class="cm-loop-alu"><span>同一个加法器 · sum + i</span><div>'+node('loop-i','这一轮的 i',s.i??'—')+'<b>→</b>'+node('loop-sum','累计 sum',s.sum??'—','cm-memory')+'</div></div><div class="cm-loop-return" data-node="loop-repeat"><b>↶</b><span>i 加 1，跳回比较</span></div></div></div>';}
    });
  }
  function branch(){const original=$('cf-branch-demo');exposeSelector('cf-branch-outcome',original);const detail=C.wrap('branch-flow',[original],'查看分支代码与各阶段记录');
    C.mount({id:'branch-flow',before:detail,controls:['#cf-branch-outcome'],action:()=>{const select=$('cf-branch-outcome');select.value=select.value==='hit'?'miss':'hit';select.dispatchEvent(new Event('change'));},actionLabel:()=> $('cf-branch-outcome').value==='hit'?'对照预测错误':'对照预测正确',
      build(){const hit=$('cf-branch-outcome').value==='hit';const words=[['预测先计算，确认路径后才提交','两种方案等待同一个 flag；正式结果 r 初始都是 0。'],['flag 还没返回，预测路径已经开始计算','等待方案还未进入分支；预测方案先按 flag = 1 计算 10 + 20。'],['30 已经算出，但还不能成为正式结果','暂存区里的 30 可以作废。此时两种方案的正式 r 都仍为 0。'],[hit?'flag = 1 返回，预测路径得到确认':'flag = 0 返回，错误路径上的 30 被丢弃',hit?'先算出的 30 可以保留，接下来才提交。等待方案此时才确定该走加法路径。':'正确路径应计算 10 − 20。错误的 30 从未写入正式结果，恢复工作还要花时间。'],[hit?'预测方案先提交 30，等待方案刚算出 30':'等待方案已算出 −10，预测方案还在恢复',hit?'提前完成的计算让预测方案更早提交相同的结果。':'猜错需要丢弃临时结果并恢复正确路径，尚未得到可提交的新值。'],[hit?'等待方案也提交 30，预测方案提前完成':'等待方案先提交 −10，预测方案刚重新算出 −10',hit?'最终结果相同，差别在于何时开始计算。':'预测错误消耗了额外的恢复工作，暂存的 −10 还要提交。'],[hit?'预测正确，节省了等待之后的计算时间':'预测错误，恢复后仍得到正确的 −10',hit?'两种方案的正式结果都是 30；预测计算没有跳过条件确认。':'两种方案的正式结果都是 −10；错误路径的 30 留在丢弃区，从未成为正式结果。']];
        const phases=words.map(([title,note],step)=>{const s=OSLabCPUVisuals.branchState(hit,step),before=OSLabCPUVisuals.branchState(hit,Math.max(0,step-1)),moves=[];for(const lane of ['baseline','predicted']){if(s[lane].pending!==null&&before[lane].pending===null)moves.push({from:lane+'-calc',to:lane+'-pending',text:s[lane].pending,type:'cm-copy'});if(s[lane].committed&&!before[lane].committed)moves.push({from:lane+'-pending',to:lane+'-result',text:s[lane].result,type:'cm-copy'});}if(step===3&&!hit)moves.push({from:'predicted-pending',to:'branch-discard',text:'30',type:'cm-discard',remove:true});return P(s,title,note,{before,moves,id:'stage-'+step,duration:step?1900:1200,during:step===3&&!hit?'错误的 30 正在丢弃，正式 r 保持 0':moves.some(m=>m.to.endsWith('-result'))?'已确认的结果正在提交':'计算结果正在进入暂存区',duringNote:step===3&&!hit?'flag 已返回 0；错误的临时结果只能丢弃，不能写入正式结果。':'移动中的值还没有完成写入，目标位置保留原来的状态。'});});return{context:'相同条件等待 · 阶段只表示先后，不代表 CPU 周期',hit,phases};},
      view(s,{phase,moving}){const flag=moving&&phase.state.step===3?phase.state.flag:s.flag;return '<div class="cm-branch-scene"><div class="cm-branch-flag">'+(flag===null?'flag 尚未返回': 'flag = '+flag+' 已返回，走'+(flag?'加法':'减法')+'路径')+'</div><div class="cm-branch-pair">'+['baseline','predicted'].map(lane=>{const x=s[lane],predict=lane==='predicted';return '<div class="cm-branch-lane"><h4>'+(predict?'先预测执行':'等待条件返回')+'</h4><div class="cm-branch-calc" data-node="'+lane+'-calc">'+(x.committed?'计算完成':!predict&&flag===null?'等待 flag':predict&&s.discarded&&s.step===4?'恢复正确路径':(flag===0?'10 − 20':'10 + 20'))+'</div>'+node(lane+'-pending','暂存结果',x.pending??'—','cm-pending')+'<div class="cm-commit-gate">'+(flag===null?'⊣ 尚不能提交':predict&&s.discarded&&s.step<5?'× 错误结果不能提交':'↓ 确认后提交')+'</div>'+node(lane+'-result','正式 r',x.result,'cm-memory')+'</div>';}).join('')+'</div><div class="cm-discard-bin" data-node="branch-discard">'+(s.discarded?'<b>× <s>30</s></b><span>错误路径的结果已作废</span>':'<span>错误预测的临时结果会丢弃</span>')+'</div></div>';}
    });
  }
  register();program();branch();
})();